use std::collections::VecDeque;impl Solution{pub fn find_min_height_trees(n:i32,e:Vec<Vec<i32>>)->Vec<i32>{if n==1{return vec![0]}let n=n as usize;let mut g=vec![vec![];n];let mut d=vec![0;n];for x in e{let(a,b)=(x[0]as usize,x[1]as usize);g[a].push(b);g[b].push(a);d[a]+=1;d[b]+=1;}let mut q=VecDeque::new();for i in 0..n{if d[i]==1{q.push_back(i)}}let mut left=n;while left>2{let z=q.len();left-=z;for _ in 0..z{let u=q.pop_front().unwrap();for &v in &g[u]{d[v]-=1;if d[v]==1{q.push_back(v)}}}}q.into_iter().map(|x|x as i32).collect()}}
